function validate(input) {
  const [{ Student = [] }] = input;
  const counts = { America: 0, Asia: 0, Europe: 0 }, spelled = new Map();
  for (const [name, continent] of Student) {
    if (name === null) return 'Every student needs a name.';
    if (!(continent in counts)) return `Unknown continent ${continent}.`;
    counts[continent]++;
    const key = `${continent}|${name.toLowerCase()}`;
    if (spelled.has(key) && spelled.get(key) !== name) return `${spelled.get(key)} and ${name} differ only in case.`;
    spelled.set(key, name);
  }
  if (counts.America < counts.Asia || counts.America < counts.Europe) return 'America must have the most students.';
  return null;
}

