function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pool = ['Jack', 'Jane', 'Xi', 'Pascal', 'Ana', 'bo', 'Mia', 'Li', 'Omar', 'Zoe'];
  const syllables = ['ka', 'ro', 'li', 'ma', 'ne', 'to', 'su', 'vi', 'da', 'xe'];
  const name = () => {
    if (small) return pick(pool);
    const text = pick(syllables) + pick(syllables) + pick(syllables);
    return text[0].toUpperCase() + text.slice(1);
  };
  // Choose the three group sizes first, with America the largest (ties allowed).
  let sizes;
  if (small) {
    sizes = [0, 1, 2].map(() => Math.floor(rand() * 4));
    const most = Math.max(...sizes);
    sizes[sizes.indexOf(most)] = sizes[0];
    sizes[0] = most;
  } else sizes = [650, 300 + Math.floor(rand() * 351), 300 + Math.floor(rand() * 351)];
  const Student = [];
  ['America', 'Asia', 'Europe'].forEach((continent, i) => {
    for (let j = 0; j < sizes[i]; j++) Student.push([name(), continent]);
  });
  for (let i = Student.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Student[i], Student[j]] = [Student[j], Student[i]];
  }
  return [{ Student }];
}
